import java.util.*;

class Solution {
  public List<String> generateSentences(List<List<String>> synonyms, String text) {
    Map<String, String> parent = new HashMap<>();
    for (List<String> p : synonyms) union(parent, p.get(0), p.get(1));
    Map<String, TreeSet<String>> groups = new HashMap<>();
    for (String w : new ArrayList<>(parent.keySet())) groups.computeIfAbsent(find(parent, w), k -> new TreeSet<>()).add(w);
    String[] words = text.split(" ");
    List<String> res = new ArrayList<>();
    build(words, 0, new ArrayList<>(), parent, groups, res);
    Collections.sort(res);
    return res;
  }

  private void build(String[] words, int i, List<String> cur, Map<String, String> parent, Map<String, TreeSet<String>> groups, List<String> res) {
    if (i == words.length) {
      res.add(String.join(" ", cur));
      return;
    }
    Set<String> options = parent.containsKey(words[i]) ? groups.get(find(parent, words[i])) : Collections.singleton(words[i]);
    for (String w : options) {
      cur.add(w);
      build(words, i + 1, cur, parent, groups, res);
      cur.remove(cur.size() - 1);
    }
  }

  private String find(Map<String, String> p, String x) {
    p.putIfAbsent(x, x);
    String r = p.get(x);
    if (!r.equals(x)) {
      r = find(p, r);
      p.put(x, r);
    }
    return r;
  }

  private void union(Map<String, String> p, String a, String b) {
    p.put(find(p, a), find(p, b));
  }
}
